// Re-key form-uploaded binaries to predictable data_<i> keys.
const items = $input.all();
const out = [];
for (const item of items) {
  const newItem = { json: { ...item.json }, binary: {} };
  let i = 0;
  if (item.binary) {
    for (const key of Object.keys(item.binary)) {
      newItem.binary[`data_${i}`] = item.binary[key];
      i++;
    }
  }
  newItem.json.source_count = i;
  out.push(newItem);
}
return out;

// Consolidate tenant lookup + config onto a single object.
// PostgREST single-row arrays are flattened by n8n HTTP node v4 — use $json.id, not $json[0].id.
const incoming = $('Normalize Binary').item;
const tenant = $('Lookup Tenant').item.json;
const cfgRow = $('Load Tenant Config').item.json;

return [{
  json: {
    ...incoming.json,
    tenant_id:    tenant.id,
    tenant_slug:  tenant.slug,
    tenant_name:  tenant.business_name,
    tenant_tier:  tenant.tier,
    config:       cfgRow.config || {}
  },
  binary: incoming.binary || {}
}];

// Fan binaries into per-source items. Binary is fetched from Merge Tenant Context
// because intervening HTTP nodes drop binary from the data chain.
const upstream = $('Merge Tenant Context').first();
const batchRow = $input.first().json;
const binaries = upstream.binary || {};
const keys = Object.keys(binaries).filter(k => k.startsWith('data_'));

const out = [];
for (let i = 0; i < keys.length; i++) {
  out.push({
    json: {
      ...upstream.json,
      batch_id:     batchRow.id,
      review_token: batchRow.review_token,
      source_index: i,
      binary_key:   keys[i]
    },
    binary: { data: binaries[keys[i]] }
  });
}
return out;

