// Parse GPT-4o Vision response into a rich dish object.
const j = $input.item.json;
const raw = j.choices?.[0]?.message?.content || '{}';

let dish = {};
try {
  const cleaned = raw.replace(/```json|```/g, '').trim();
  dish = JSON.parse(cleaned);
} catch (e) {
  dish = { dish_name: 'Unknown dish', components: [], distinctive_features: [], plating: '', vessel: '' };
}

const components = (dish.components || []).join(', ');
const dish_description = `${dish.dish_name || 'a dish'}${components ? ': ' + components : ''}`;

return {
  json: {
    ...j,
    dish,
    dish_description,
    recommended_shot_types: ['hero_moody']
  }
};

// Pin all per-source context that downstream variant nodes need.
// CRITICAL: must carry the rich `dish` object — bake-off Build Prompt depends on it.
const inserted = $input.item.json;
const itemId = inserted.id || (Array.isArray(inserted) ? inserted[0]?.id : null);

return {
  json: {
    item_id:          itemId,
    batch_id:         $('Create Batch').item.json.id,
    tenant_id:        $('Merge Tenant Context').item.json.tenant_id,
    tenant_slug:      $('Merge Tenant Context').item.json.tenant_slug,
    source_drive_url: $('Build Source URL').item.json.source_drive_url,
    source_drive_id:  $('Build Source URL').item.json.source_drive_id,
    dish:             $('Parse Vision').item.json.dish,
    dish_description: $('Parse Vision').item.json.dish_description,
    config:           $('Merge Tenant Context').item.json.config
  }
};

// Full bake-off — fans out to 8 prompt variants per source.
const variants = [
  { variant_slug: 'hero_moody',      variant_name: 'Hero — Moody Editorial' },
  { variant_slug: 'hero_bright',     variant_name: 'Hero — Bright Daylight' },
  { variant_slug: 'topdown_props',   variant_name: 'Top-down — Editorial Flat-lay' },
