  dish.dish_name || 'a dish',
  components ? ` — ${components}` : '',
  distinctive ? `. ${distinctive}` : '',
  dish.plating ? `. Plating: ${dish.plating}` : '',
  dish.vessel ? `. Served in/on: ${dish.vessel}` : ''
];
const subject = subjectParts.join('').trim().replace(/\.+$/, '') + '.';

// ===================================================================
// Reference metadata extraction & scene-block composition
// ===================================================================
const sortByRecency = (arr) => (arr || [])
  .filter(r => typeof r === 'object' && r !== null && r.url && r.summary)
  .sort((a, b) => new Date(b.added_at || 0) - new Date(a.added_at || 0));

// --- Interior refs (v3) -------------------------------------------------
const interiorRefs = sortByRecency(ctx.config?.references?.interior);
const activeInterior = interiorRefs[0] || null;

const composeInteriorSceneBlock = (ref) => {
  if (!ref) return null;
  const lines = [`REFERENCE SCENE: ${ref.summary}`];
  if (ref.palette?.length)   lines.push(`COLOUR PALETTE: ${ref.palette.join(', ')}`);
  if (ref.lighting)          lines.push(`LIGHTING CHARACTER: ${ref.lighting}`);

  // v3.4: Vision tends to flatten "the table material" with "other things in the room
  // made of various materials" (chair frames, floors, trim, walls, fixtures) into one
  // undifferentiated array. The model then can't tell which entry describes the table.
  // Fix: regex-extract the table-tagged entry; relabel the rest as atmospheric context only.
  const tableRegex = /\b(table|tabletop|surface|countertop)\b/i;
  const allMaterials = ref.materials || [];
  const tableMaterial = allMaterials.find(m => tableRegex.test(m));
  const otherMaterials = allMaterials.filter(m => !tableRegex.test(m));

  if (tableMaterial) {
    lines.push(`TABLETOP MATERIAL (THE ACTUAL TABLE SURFACE — use this and ONLY this for the table): ${tableMaterial}`);
  } else if (allMaterials.length) {
    lines.push(`TABLETOP MATERIAL (THE ACTUAL TABLE SURFACE): premium restaurant tabletop consistent with the venue's character — NOT walnut or dark wood unless explicitly indicated`);
  }
  if (otherMaterials.length) {
    lines.push(`OTHER MATERIALS IN SPACE (atmospheric context only — these describe walls, chairs, frames, floors, fixtures; they MUST NOT drive the table surface): ${otherMaterials.join(', ')}`);
  }

  if (ref.mood)              lines.push(`AMBIENT MOOD: ${ref.mood}`);
  if (ref.composition_cues)  lines.push(`SCENE COMPOSITION: ${ref.composition_cues}`);
  return lines.join('\n');
};

const interiorBlock = composeInteriorSceneBlock(activeInterior);

// --- Style refs (v3.1, NEW) --------------------------------------------
const styleRefs = sortByRecency(ctx.config?.references?.style);
const activeStyle = styleRefs[0] || null;

const composeStyleSceneBlock = (ref) => {
  if (!ref) return null;
  const lines = [`REFERENCE STYLING: ${ref.summary}`];
  if (ref.palette?.length)   lines.push(`COLOUR PALETTE: ${ref.palette.join(', ')}`);
