  if (ref.lighting_on_food)  lines.push(`LIGHTING ON FOOD: ${ref.lighting_on_food}`);
  if (ref.surface)           lines.push(`SURFACE: ${ref.surface}`);
  if (ref.mood)              lines.push(`STYLING MOOD: ${ref.mood}`);
  if (ref.composition_cues)  lines.push(`STYLING COMPOSITION: ${ref.composition_cues}`);
