// Uses this.helpers.httpRequest (NOT $http.request — that is not exposed in this n8n version).
const j = $input.item.json;
const url = j.polling_url;
const headers = { Authorization: `Token ${$env.REPLICATE_API_TOKEN}` };

let status = 'starting';
let result = null;
const maxAttempts = 24;       // 24 × 10s = 4 min ceiling per prediction
const intervalMs = 10000;

for (let i = 0; i < maxAttempts; i++) {
  await new Promise(r => setTimeout(r, intervalMs));
  result = await this.helpers.httpRequest({ method: 'GET', url, headers, json: true });
  status = result.status;
  if (status === 'succeeded' || status === 'failed' || status === 'canceled') break;
}

if (status !== 'succeeded') {
  throw new Error(`Replicate prediction ${status}: ${result?.error || 'no error message'}`);
}

const output = Array.isArray(result.output) ? result.output[0] : result.output;

return {
  json: {
    ...j,
    replicate_status: status,
    replicate_output_url: output
  }
};

