// Field-name assumptions (adjust if your upstream nodes use different keys):
//   j.output_drive_url — public Drive URL of the generated image
//   j.output_drive_id  — Drive file ID
//   j.final_prompt     — the prompt that was sent to Replicate

const items = $input.all();
const ctx = $('Pin Item Context').item.json;

const shot_set = {};

